window.POETRY_REGISTER("v5-strict-12-9-0-a551d1a900c7.js",{"poems":[[52811,2],[53327,2],[123678,7],[124302,7],[151568,7],[191567,7],[206317,7],[215620,7],[262733,7],[291411,7],[374585,10],[435684,8],[442638,8],[458061,8],[465489,8],[575728,8],[589894,8],[596184,8],[647564,15],[650074,5],[703336,5],[722255,5]],"pairs":[["同书复录雷威大历三年题字","知欧雷并非同时之人",0],["我不知尔是人耶猿耶复猱耶","教我见尔为尔长叹嗟",1],["君不见斗茶公子不忍斗小团","上有双衔绶带双飞鸾",2],["君不见东海孝妇死作三年干","不如广汉庞姑去却还",3],["所以道十五日已前点即不到","十五日已后到即不点",4],["君不见一声霹雳兮雾罩长空","千眼顿开兮云收岳面",5],["君不见蒲萄一斗换得西凉州","不如将军告身供一醉",6],["君不见东林怪蔓之诗三百年","字如金绳铁索相纠缠",7],["君不见蜀山之高直上登云梯","草边路侧多少豹狼蹄",8],["君不见绥和天子在御世五春","画堂甲观寂寂空无人",9],["君不见天台嵯峨四万八十丈","若非飙车羽轮那得上",10],["又不见终南盘亘中原五百里","天梯云栈悬绝那可履",10],["后土何不令空青出土泥沙然","大使何君疗人双目全",11],["其间兮只疑方壶圆峤之在目","丹厓翠壁掩映而霄峥",12],["君不见泰山高高梁甫在其半","古来封坛禅地无宫馆",13],["君不见武穆高扁在堂垂无极","我师一经之歌将无同",14],["又莫是早年出入宫禁侍虞舜","记得五弦琴上南风诗",15],["愿公事业与此数公者争先驱","然后归作睢阳五老图",16],["豫章之山盘盘乎巀嶪而倚天","石璧万仞荒㫚嘘云烟",17],["君不见一县图书七百四十一","日造黄册堆积高于山",18],["嫌好那毛达撒的皮子不中看","弄斯文又制下衣和冠",19],["净弄的火老鸦落屋没有正讲","河崖上两场瞎关了兵",19],["统前后混了一百九十单八载","大唐天子才主了中华",19],["李三娘的汉子又做了刘高祖","咬脐郎登极忒也软匝",19],["吁嗟乎人生百年为乐能几何","何不反哭为笑而长歌",20],["君不见古来让以天下惟恐浼","世间尚有洗耳沉渊人",21]]});
